  (let [arguments {:name arg-name}] (runtime/invoke-field self "Workspace" "module" arguments)))

(defn module-source
  "Load a module source from a path within the workspace.\n\nRelative paths (e.g., \"foo\") resolve from the workspace cwd; absolute paths (e.g., \"/foo\") resolve from the workspace root.\n\nFails if the path does not point to an initialized module."
  [self arg-path]
  (let [arguments {:path arg-path}]
    (runtime/invoke-field self "Workspace" "moduleSource" arguments)))

(defn cwd
  "Current location within the workspace root.\n\nThe workspace root is returned as \"/\".\n\nRelative paths in workspace APIs resolve from here."
  [self]
  (let [arguments {}] (runtime/invoke-field self "Workspace" "cwd" arguments)))

(defn artifacts
  "Discover static object artifacts from workspace modules without evaluating their values.\n\nOmits the paths that the workspace's check.skip, generate.skip, and up.skip settings skip.\nOptions: :include"
  ([self] (artifacts self {}))
  ([self options]
    (when-not (map? options)
      (throw (ex-info "Options must be a map" {:type :dagger/invalid-argument})))
    (let [arguments (merge options {})]
      (runtime/invoke-field self "Workspace" "artifacts" arguments))))

(defn migrate
  "Plan the explicit migration needed for the current workspace.\n\nInclude installed local modules and their local dependencies. Other module candidates remain unchanged unless selected.\n\nThe returned plan has an empty changeset and no steps when no migration is needed.\nOptions: :modules"
  ([self] (migrate self {}))
  ([self options]
    (when-not (map? options)
      (throw (ex-info "Options must be a map" {:type :dagger/invalid-argument})))
    (let [arguments (merge options {})]
      (runtime/invoke-field self "Workspace" "migrate" arguments))))

(defn address
  "Canonical Dagger address of the workspace location, or an opaque identity for synthetic workspaces."
  [self]
  (let [arguments {}] (runtime/invoke-field self "Workspace" "address" arguments)))
